      out.write("// 学生管理画面の最適化されたJavaScript\r\n");
      out.write("\r\n");
      out.write("// アクセシビリティの向上\r\n");
      out.write("document.addEventListener('DOMContentLoaded', () => {\r\n");
      out.write("    // キーボードナビゲーションの改善\r\n");
      out.write("    const actionButtons = document.querySelectorAll('.action-btn');\r\n");
      out.write("    actionButtons.forEach(button => {\r\n");
      out.write("        button.addEventListener('keydown', (e) => {\r\n");
      out.write("            if (e.key === 'Enter' || e.key === ' ') {\r\n");
      out.write("                e.preventDefault();\r\n");
      out.write("                button.click();\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    // カードリンクのキーボード操作\r\n");
      out.write("    const cardLinks = document.querySelectorAll('.card-link');\r\n");
      out.write("    cardLinks.forEach(link => {\r\n");
      out.write("        link.addEventListener('keydown', (e) => {\r\n");
      out.write("            if (e.key === 'Enter' || e.key === ' ') {\r\n");
      out.write("                e.preventDefault();\r\n");
      out.write("                link.click();\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    // フォーカス管理の改善\r\n");
      out.write("    const focusableElements = document.querySelectorAll('a, button, input, select, textarea, [tabindex]:not([tabindex=\"-1\"])');\r\n");
      out.write("    focusableElements.forEach(element => {\r\n");
      out.write("        element.addEventListener('focus', () => {\r\n");
      out.write("            element.style.outline = '2px solid #2C7744';\r\n");
      out.write("            element.style.outlineOffset = '2px';\r\n");
      out.write("        });\r\n");
      out.write("        \r\n");
      out.write("        element.addEventListener('blur', () => {\r\n");
      out.write("            element.style.outline = '';\r\n");
      out.write("            element.style.outlineOffset = '';\r\n");
      out.write("        });\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    // 統計データのアニメーション\r\n");
      out.write("    const statNumbers = document.querySelectorAll('.stat-number');\r\n");
      out.write("    const observer = new IntersectionObserver((entries) => {\r\n");
      out.write("        entries.forEach(entry => {\r\n");
      out.write("            if (entry.isIntersecting) {\r\n");
      out.write("                const target = entry.target;\r\n");
      out.write("                const finalValue = parseInt(target.textContent);\r\n");
      out.write("                animateNumber(target, 0, finalValue, 1000);\r\n");
      out.write("                observer.unobserve(target);\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    statNumbers.forEach(stat => observer.observe(stat));\r\n");
      out.write("});\r\n");
      out.write("\r\n");
      out.write("// 数値アニメーション関数\r\n");
      out.write("function animateNumber(element, start, end, duration) {\r\n");
      out.write("    const startTime = performance.now();\r\n");
      out.write("    \r\n");
      out.write("    function updateNumber(currentTime) {\r\n");
      out.write("        const elapsed = currentTime - startTime;\r\n");
      out.write("        const progress = Math.min(elapsed / duration, 1);\r\n");
      out.write("        \r\n");
      out.write("        const current = Math.floor(start + (end - start) * progress);\r\n");
      out.write("        element.textContent = current;\r\n");
      out.write("        \r\n");
      out.write("        if (progress < 1) {\r\n");
      out.write("            requestAnimationFrame(updateNumber);\r\n");
      out.write("        }\r\n");
      out.write("    }\r\n");
      out.write("    \r\n");
      out.write("    requestAnimationFrame(updateNumber);\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// パフォーマンス最適化\r\n");
      out.write("window.addEventListener('load', () => {\r\n");
      out.write("    // 画像の遅延読み込み\r\n");
      out.write("    const images = document.querySelectorAll('img[data-src]');\r\n");
      out.write("    const imageObserver = new IntersectionObserver((entries, observer) => {\r\n");
      out.write("        entries.forEach(entry => {\r\n");
      out.write("            if (entry.isIntersecting) {\r\n");
      out.write("                const img = entry.target;\r\n");
      out.write("                img.src = img.dataset.src;\r\n");
      out.write("                img.removeAttribute('data-src');\r\n");
      out.write("                observer.unobserve(img);\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    images.forEach(img => imageObserver.observe(img));\r\n");
      out.write("\r\n");
      out.write("    // スムーズスクロール\r\n");
      out.write("    const smoothScrollLinks = document.querySelectorAll('a[href^=\"#\"]');\r\n");
      out.write("    smoothScrollLinks.forEach(link => {\r\n");
      out.write("        link.addEventListener('click', (e) => {\r\n");
      out.write("            e.preventDefault();\r\n");
      out.write("            const targetId = link.getAttribute('href').substring(1);\r\n");
      out.write("            const targetElement = document.getElementById(targetId);\r\n");
      out.write("            \r\n");
      out.write("            if (targetElement) {\r\n");
      out.write("                targetElement.scrollIntoView({\r\n");
      out.write("                    behavior: 'smooth',\r\n");
      out.write("                    block: 'start'\r\n");
      out.write("                });\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("    });\r\n");
      out.write("});\r\n");
      out.write("\r\n");
      out.write("// エラーハンドリング\r\n");
      out.write("window.addEventListener('error', (e) => {\r\n");
