      out.write("    // エラーが発生した場合のフォールバック処理\r\n");
      out.write("});\r\n");
      out.write("\r\n");
      out.write("// ページの可視性変更時の処理\r\n");
      out.write("document.addEventListener('visibilitychange', () => {\r\n");
      out.write("    if (document.hidden) {\r\n");
      out.write("        // ページが非表示になった時の処理\r\n");
      out.write("        console.log('Page hidden');\r\n");
      out.write("    } else {\r\n");
      out.write("        // ページが表示された時の処理\r\n");
      out.write("        console.log('Page visible');\r\n");
      out.write("    }\r\n");
      out.write("});\r\n");
      out.write("</script>\r\n");
      out.write("\r\n");
      out.write("</body>\r\n");
